"""V-914 pilot: 20 tasks, statement from commit message + symptom. Hidden tests = test files of the commit.
name_req marks statements that unavoidably state an interface literal the hidden test checks."""
WRAP = ("You are working in the current directory, a snapshot of a software project (no git history, no tests). "
        "Work only inside this directory; do not read or list anything outside it.\n\n")
FMT = "\n\nEdit the files in this directory in place. Final answer: two or three sentences saying what you changed."
T = {}
def t(id, commit, text, name_req=False):
    T[id] = dict(commit=commit, prompt=text + FMT, name_req=name_req)

t("P01", "8bd9bd60", "In app/workspace.py the function that reports a worker branch's work-in-progress status computes per-file insertion/deletion counts against a base ref. When the base branch has moved on after the worker branch was created, the counts wrongly include the base branch's own new changes (a file changed only on the base shows up as deletions in the worker's list).\nRequired: the counts reflect only the worker's own changes since the branch point; uncommitted work is still included.")
t("P02", "9947ae37", "In app/rag.py, background RAG embedding uses too much CPU in the web process: with the current default of two ONNX threads it was measured at about 200% CPU.\nRequired: the default number of ONNX threads is 1, and the RAG_ONNX_THREADS environment variable still overrides it.")
t("P03", "c3e66f16", "Managed Codex sessions get a generated config that carries over only a few keys from the user's base Codex config (app/backend_codex.py), so the user's enlarged context window setting is lost and the session runs with a small window.\nRequired: the generated config also carries over model_context_window and model_auto_compact_token_limit from the base config, with their values unchanged.")
t("P04", "2ee5279f", "When a Telegram message arrives in a topic that is not mapped to any agent (app/tg_bridge.py), the bot posts an error reply into that chat, which is noise for people using the group.\nRequired: nothing is sent to Telegram in that case; the situation is still logged and the message is still not delivered to any agent.")
t("P05", "baaa4858", "app/merge_test_gate.py, run_pytest: output containing the text 'No module named pytest' anywhere is classified as 'pytest unavailable' (inconclusive). A real test whose own assertion message contains that text is therefore misclassified.\nRequired: 'pytest unavailable' only when stdout is empty and stderr is exactly '<python executable as passed>: No module named pytest' (the executable's base name instead of the full path is also accepted). Everything else goes through normal pass/fail classification.")
t("P06", "f1eafe04", "With dashboard authentication enabled, /docs, /redoc and /openapi.json can be opened without logging in, exposing the API schema (app/auth.py decides which paths need auth).\nRequired: these three paths require authentication like the /api/ paths do; with a valid session cookie /openapi.json still returns the schema.")
t("P07", "cfdb1d0e", "app/db.py, silence_mark_announced: it records that the quota-silence notice was delivered with an UPDATE of the single row (id=1) in table quota_silence. If that row does not exist (never created, or erased), nothing is recorded and the notice is later repeated.\nRequired: when the row is missing it is created atomically (silence_since = the given time, notified_at empty, announced_at = the given time); when it exists only announced_at changes.")
t("P08", "d987193b", "The Telegram turn anchor (app/tg_bridge.py) starts with a bar of heavy horizontal line characters. At 20 characters it wraps onto a second line in a phone chat bubble.\nRequired: the bar is exactly 19 characters; its width lives in a single module-level constant named _ANCHOR_BAR_WIDTH that the code uses to build the bar.", name_req=True)
t("P09", "fa1b1355", "Every time the MCP server configuration is rebuilt for a session (for example after a rename or refresh while its MCP process is still serving a turn), a new proof secret is issued, and the secret held by the running MCP process stops validating, so its calls get rejected (app/mcp_proof.py, app/manager.py).\nRequired: building the configuration again for the same session id reuses the session's existing proof, so a check of the earlier proof still succeeds.")
t("P10", "23ea33d8", "app/tm.py: when the next task number of a project is allocated it can hand out a number N although the directory <project scope>/docs/tasks/N/ already exists (such directories outlive deleted tasks).\nRequired: numbers whose directory exists are skipped, continuing upward to the first free one, also when the database maximum is lower; a project without a scope behaves as before.")
t("P11", "8dd5befc", "In app/routes/sessions.py, the branch-switch handler, when the worker is already on the correct branch bound to the task and the binding is healthy, returns the 'already_current' response with an extra task_status field.\nRequired: that response consists exactly of ok (true), state ('already_current'), branch, waited_seconds and message (message text unchanged) - no other fields.")
t("P12", "69a88105", "The shell command policy (app/shell_policy.py) rejects recursive find and recursive grep with advice to use rg. On a host where rg is not installed that leaves the agent no way to search.\nRequired: the recursive find/grep rules apply only when rg is available on PATH (use shutil.which); when rg is not available these commands are allowed (no violation reported).")
t("P13", "4b185fdc", "app/merge_test_gate.py, run_pytest: when the pytest subprocess times out, subprocess.TimeoutExpired may carry stdout/stderr as bytes, str or None in any combination, and combining them raises TypeError.\nRequired: each stream is normalized to str (bytes decoded as UTF-8 with replacement characters, None becomes empty), the output is stdout followed by stderr, and the result stays status inconclusive with reason 'timeout'.")
t("P14", "3b84786d", "During a restart pause the server (app/main.py) refuses mutating requests with 503, but ordinary responses say nothing about it, so a client that never got refused cannot tell the pause started or ended.\nRequired: every HTTP response, including the 503 refusals, carries the header X-Orchestra-Restarting with value '1' while mutating requests are being refused and '0' while admission is open.")
t("P15", "bf70e3ad", "The merge test gate (app/merge_test_gate.py) splits more than 12 test files into batches of 12 sorted by size, e.g. 14 files become [2, 12], and the 12-file batch exceeds the time budget.\nRequired: when there are more than 12 files, split them, keeping their order, into the fewest batches of at most 6 files each, with sizes as even as possible (14 files -> 5, 5, 4). Up to 12 files stay one batch.")
t("P16", "12ed3d3d", "In the dashboard send-message route (app/routes/sessions.py), when dashboard authentication is disabled (no user/password configured) a message sent without an explicit sender is recorded with origin 'unknown', because a session cookie can never validate in that setup.\nRequired: with authentication disabled the sender is treated as the operator (origin 'user'); with authentication enabled the existing cookie check decides as before.")
t("P17", "96192b40", "Role validation for spawning (find validate_spawn in app/) in fail-open validation mode lets an unknown parent or child role through, which bypasses the can_spawn whitelist entirely.\nRequired: an unknown parent role or unknown child role always raises ValueError, in both fail-closed and fail-open modes (keep the existing messages 'unknown parent role ...' and 'unknown role ...'); can_spawn ['*'] means any known role; known roles keep obeying their whitelists.")
t("P18", "f590cdd1", "app/quota_gate.py, deciding_window: for Codex-type buckets it picks the deciding quota window by field name 'primary'. OpenAI changed one pool to two windows (primary = 5 hours, secondary = 7 days); the 0% five-hour window hid a 100% weekly one and the gate admitted workers into an exhausted pool.\nRequired: for these buckets choose the window with the longest window_minutes (a missing or invalid length counts as 0); Anthropic buckets keep requiring the weekly window (no weekly window -> no data); single-window cases behave as before.")
t("P19", "88682bef", "app/codex_review_artifact.py: when usage accounting cannot be done (an older caller does not pass the usage arguments on the command line, or recording usage raises, e.g. zero-token usage), the review is lost or the command fails.\nRequired: the review result is always written to the output file and the exit status stays 0; the accounting problem is recorded as a line starting 'Codex usage unaccounted: ' (followed by the reason) appended to the output file and printed to stderr.", name_req=True)
t("P20", "8b6c8b50", "The Bash tool hook classifier (app/backend_claude.py, _classify_bash_payload) lets through grep patterns with large bounded repetition such as '.{0,100}word.{0,100}'; inside the claude binary these exhaust memory (5.9 GB observed).\nRequired: for grep, egrep, ugrep and rg commands, a bounded quantifier {m,N} with upper bound N of 20 or more (on '.', a backslash class or a [...] set) is classified 'regex_blowup' and blocked with an explanatory message; narrow patterns such as 'foo.*bar', '\\w{1,5}' and plain words stay allowed; a classifier exception still fails open.", name_req=True)
